/**
 * The CAD modify operations: addCircle, addArc, copy, scale, mirror, offset,
 * trim, extend, setLine, setPolyline and the three layer-table operations.
 *
 * The fixture is a committed synthetic drawing (`cadops.dxf`, regenerated by
 * fixtures/generate.mjs), never the owner's print set. Every test opens its own
 * copy, so an operation can never see a previous test's edits.
 */
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { applyOps, buildSheetModel, dxfBytes, openSheet, validateOps, verifyWritten } from '../src/engine/index.ts'
import { fixturesDir, ok } from './helpers.mjs'

const CAD_FIXTURE = 'cadops.dxf'

/** Tolerance for comparing drawing-unit coordinates. */
const TOL = 1e-6

/** Open a fresh copy of the modify-operation fixture. */
async function openCad() {
  return openSheet({ path: CAD_FIXTURE, bytes: new Uint8Array(readFileSync(join(fixturesDir, CAD_FIXTURE))) })
}

/** The model's model-space primitives that are not flattened block content. */
function topEntities(model) {
  return model.layouts.find(layout => layout.id === 'Model').entities.filter(entity => !entity.g)
}

/** True when a number is within tolerance of an expected value. */
function near(actual, expected, tolerance = TOL) {
  return typeof actual === 'number' && Math.abs(actual - expected) <= tolerance
}

/** True when a point is within tolerance of an expected point. */
function nearPoint(point, expected, tolerance = TOL) {
  return Array.isArray(point) && near(point[0], expected[0], tolerance) && near(point[1], expected[1], tolerance)
}

/** True when a point list matches an expected point list within tolerance. */
function nearPoints(points, expected, tolerance = TOL) {
  return Array.isArray(points) && points.length === expected.length && points.every((point, index) => nearPoint(point, expected[index], tolerance))
}

/** Ids of the fixture's named geometry, found by shape rather than handle. */
function idsOf(model) {
  const entities = topEntities(model)
  const line = (a, b) => {
    const found = entities.find(entity => entity.k === 'line' && nearPoints(entity.pts, [a, b]))
    ok(found, `expected a line ${JSON.stringify([a, b])}`)
    return found.id
  }
  const circle = entities.find(entity => entity.k === 'circle' && nearPoint(entity.c, [20, 5]))
  ok(circle, 'expected the circle at 20,5')
  const arc = entities.find(entity => entity.k === 'arc' && nearPoint(entity.c, [30, 5]))
  ok(arc, 'expected the arc at 30,5')
  const polyline = entities.find(entity => entity.k === 'polyline')
  ok(polyline, 'expected the polyline')
  const text = entities.find(entity => entity.k === 'text' && entity.t === 'NOTE')
  ok(text, 'expected the NOTE text')
  const hatch = entities.find(entity => entity.k === 'hatch')
  ok(hatch, 'expected the hatch')
  const insert = entities.find(entity => entity.k === 'insert' && entity.block === 'MARK')
  ok(insert, 'expected the MARK insert')
  return {
    lineA: line([0, 0], [10, 0]),
    lineV: line([5, -5], [5, 5]),
    lineE: line([10, 0], [10, 4]),
    lineS: line([0, 2], [8, 2]),
    lineF: line([12, 0], [12, 1]),
    circle: circle.id,
    arc: arc.id,
    poly: polyline.id,
    text: text.id,
    hatch: hatch.id,
    insert: insert.id
  }
}

/** Apply ops to a fresh fixture and return the re-read model. */
async function applyAndReread(ops) {
  const opened = await openCad()
  const result = applyOps(opened, ops)
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  return { opened, result, after }
}

test('validateOps accepts a draft using every new operation', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  // addLayer comes first so the addCircle can use the layer it creates.
  const ops = [
    { op: 'addLayer', name: 'MARKUP', color: 5 },
    { op: 'addCircle', layout: 'Model', center: [70, 0], radius: 1.5, layer: 'MARKUP' },
    { op: 'addArc', layout: 'Model', center: [75, 0], radius: 2, startAngleDeg: 30, endAngleDeg: 120 },
    { op: 'copy', layout: 'Model', ids: [ids.lineA], dx: 0, dy: 20 },
    { op: 'scale', layout: 'Model', ids: [ids.circle], center: [20, 5], factor: 2 },
    { op: 'mirror', layout: 'Model', ids: [ids.poly], axisA: [0, 0], axisB: [1, 0] },
    { op: 'offset', layout: 'Model', id: ids.lineA, distance: 3, side: [0, 1] },
    { op: 'trim', layout: 'Model', id: ids.lineA, boundaryId: ids.lineV, pick: [10, 0] },
    { op: 'extend', layout: 'Model', id: ids.lineS, boundaryId: ids.lineE },
    { op: 'setLine', layout: 'Model', id: ids.lineF, a: [12, 0], b: [12, 2] },
    { op: 'setPolyline', layout: 'Model', id: ids.poly, pts: [[40, 0], [46, 0], [46, 4]], closed: true },
    { op: 'setLayerColor', name: 'GEOM', color: 6 },
    { op: 'renameLayer', from: 'TEXT', to: 'ANNOTATION' }
  ]
  const validation = validateOps(opened, ops)
  assert.deepEqual(validation.errors, [])
  assert.equal(validation.ok, true)
  ok(validation.notes.some(note => note.includes('layer MARKUP will be created') || note.includes('MARKUP')))
  ok(validation.notes.some(note => note.includes('renamed')))
  // Layer-table operations carry no layout field and must validate without one.
  assert.equal(validateOps(opened, [{ op: 'addLayer', name: 'BARE' }]).ok, true)
  assert.equal(validateOps(opened, [{ op: 'setLayerColor', name: 'GEOM', color: 3 }]).ok, true)
  assert.equal(validateOps(opened, [{ op: 'renameLayer', from: 'AUX', to: 'AUX2' }]).ok, true)
})

test('validateOps rejects every class of bad modify operation with an actionable fix', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  const cases = [
    [{ op: 'addCircle', layout: 'Model', center: [0, 0], radius: 0 }, /greater than 0/],
    [{ op: 'addCircle', layout: 'Model', center: [Number.NaN, 0], radius: 1 }, /finite/],
    [{ op: 'addArc', layout: 'Model', center: [0, 0], radius: 1, startAngleDeg: 45, endAngleDeg: 405 }, /no sweep/],
    [{ op: 'addArc', layout: 'Model', center: [0, 0], radius: -1, startAngleDeg: 0, endAngleDeg: 90 }, /greater than 0/],
    [{ op: 'copy', layout: 'Model', ids: [], dx: 1, dy: 1 }, /at least one entity id/],
    [{ op: 'copy', layout: 'Model', ids: [ids.lineA], dx: 1 }, /must be present and finite/],
    [{ op: 'scale', layout: 'Model', ids: [ids.lineA], center: [0, 0], factor: 0 }, /greater than 0/],
    [{ op: 'scale', layout: 'Model', ids: [ids.hatch], center: [0, 0], factor: 2 }, /cannot edit a HATCH/],
    [{ op: 'mirror', layout: 'Model', ids: [ids.insert], axisA: [0, 0], axisB: [1, 0] }, /cannot edit a INSERT/],
    [{ op: 'mirror', layout: 'Model', ids: [ids.hatch], axisA: [0, 0], axisB: [1, 0] }, /cannot edit a HATCH/],
    [{ op: 'mirror', layout: 'Model', ids: [ids.lineA], axisA: [1, 1], axisB: [1, 1] }, /same point/],
    [{ op: 'mirror', layout: 'Model', ids: [ids.lineA], axisA: [0, 0], axisB: [1, 0], eraseSource: 'yes' }, /eraseSource must be true or false/],
    [{ op: 'offset', layout: 'Model', id: ids.poly, distance: 1 }, /cannot edit a LWPOLYLINE/],
    [{ op: 'offset', layout: 'Model', id: ids.lineA, distance: 1 }, /needs a side point/],
    [{ op: 'offset', layout: 'Model', id: ids.lineA, distance: 1, side: [5, 0] }, /side point lies on the line/],
    [{ op: 'offset', layout: 'Model', id: ids.circle, distance: 1, side: [22, 5] }, /side point lies on the circle/],
    [{ op: 'offset', layout: 'Model', id: ids.circle, distance: 2, side: [20, 5] }, /not smaller than the radius/],
    [{ op: 'trim', layout: 'Model', id: ids.circle, boundaryId: ids.lineV }, /only supports LINE entities/],
    [{ op: 'trim', layout: 'Model', id: ids.lineA, boundaryId: ids.circle }, /boundary must be a LINE/],
    [{ op: 'trim', layout: 'Model', id: ids.lineA, boundaryId: ids.lineS }, /do not intersect/],
    [{ op: 'trim', layout: 'Model', id: ids.lineS, boundaryId: ids.lineE }, /does not cross the line between its endpoints/],
    [{ op: 'trim', layout: 'Model', id: ids.lineA, boundaryId: ids.lineE }, /at an endpoint/],
    [{ op: 'extend', layout: 'Model', id: ids.circle, boundaryId: ids.lineV }, /only supports LINE entities/],
    [{ op: 'extend', layout: 'Model', id: ids.lineA, boundaryId: ids.lineS }, /parallel/],
    [{ op: 'extend', layout: 'Model', id: ids.lineA, boundaryId: ids.lineV }, /already reaches the boundary/],
    [{ op: 'extend', layout: 'Model', id: ids.lineS, boundaryId: ids.lineF }, /does not reach the boundary/],
    [{ op: 'setLine', layout: 'Model', id: ids.circle, a: [0, 0], b: [1, 1] }, /setLine cannot edit a CIRCLE/],
    [{ op: 'setLine', layout: 'Model', id: ids.lineA, a: [2, 2], b: [2, 2] }, /same point/],
    [{ op: 'setPolyline', layout: 'Model', id: ids.lineA, pts: [[0, 0], [1, 0]] }, /setPolyline cannot edit a LINE/],
    [{ op: 'setPolyline', layout: 'Model', id: ids.poly, pts: [[0, 0]] }, /at least 2 point/],
    [{ op: 'addLayer', name: 'GEOM' }, /already exists/],
    [{ op: 'addLayer', name: '' }, /layer name is empty/],
    [{ op: 'addLayer', name: 'bad/name' }, /not a legal DXF layer name/],
    [{ op: 'addLayer', name: 'NEW', color: 0 }, /not an ACI index/],
    [{ op: 'setLayerColor', name: 'MISSING', color: 5 }, /does not exist/],
    [{ op: 'setLayerColor', name: 'GEOM', color: 'red' }, /not an ACI index/],
    [{ op: 'renameLayer', from: 'MISSING', to: 'NEWNAME' }, /does not exist/],
    [{ op: 'renameLayer', from: '0', to: 'GROUND' }, /layer 0 cannot be renamed/],
    [{ op: 'renameLayer', from: 'AUX', to: 'GEOM' }, /already exists/]
  ]
  for (const [op, pattern] of cases) {
    const validation = validateOps(opened, [op])
    assert.equal(validation.ok, false, `${JSON.stringify(op)} should be rejected`)
    ok(validation.errors.length >= 1)
    assert.match(validation.errors[0].message, pattern)
    ok(validation.errors[0].fix.length > 0, `fix missing for ${JSON.stringify(op)}`)
    assert.equal(typeof validation.errors[0].opIndex, 'number')
  }
})

test('addCircle and addArc write real CIRCLE and ARC entities', async () => {
  const opened = await openCad()
  const result = applyOps(opened, [
    { op: 'addCircle', layout: 'Model', center: [70, 0], radius: 1.5, layer: 'MARKUP' },
    { op: 'addArc', layout: 'Model', center: [75, 0], radius: 2, startAngleDeg: 30, endAngleDeg: 120 }
  ])
  assert.equal(result.changes.addCircle, 1)
  assert.equal(result.changes.addArc, 1)
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  const entities = topEntities(after)
  const circle = entities.find(entity => entity.k === 'circle' && nearPoint(entity.c, [70, 0]))
  ok(circle, 'the added circle is in the re-read model')
  assert.equal(circle.r, 1.5)
  assert.equal(circle.layer, 'MARKUP')
  const arc = entities.find(entity => entity.k === 'arc' && nearPoint(entity.c, [75, 0]))
  ok(arc, 'the added arc is in the re-read model')
  assert.equal(arc.r, 2)
  assert.ok(near(arc.a0, Math.PI / 6))
  assert.ok(near(arc.a1, (2 * Math.PI) / 3))
  ok(after.layers.some(layer => layer.name === 'MARKUP'))
})

test('copy clones geometry with a fresh id and keeps the source', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  const result = applyOps(opened, [
    { op: 'copy', layout: 'Model', ids: [ids.lineA, ids.circle], dx: 0, dy: 20 }
  ])
  assert.equal(result.changes.copy, 2)
  assert.equal(result.touchedIds.length, 2)
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  const entities = topEntities(after)
  // The source stays and keeps its id.
  ok(entities.some(entity => entity.id === ids.lineA), 'the copied line keeps its source')
  ok(entities.some(entity => entity.id === ids.circle), 'the copied circle keeps its source')
  const copiedLine = entities.find(entity => entity.k === 'line' && nearPoints(entity.pts, [[0, 20], [10, 20]]))
  ok(copiedLine, 'the copied line is offset by the delta')
  assert.notEqual(copiedLine.id, ids.lineA)
  assert.equal(copiedLine.layer, 'GEOM')
  const copiedCircle = entities.find(entity => entity.k === 'circle' && nearPoint(entity.c, [20, 25]))
  ok(copiedCircle, 'the copied circle is offset by the delta')
  assert.equal(copiedCircle.r, 2)
  assert.notEqual(copiedCircle.id, ids.circle)
})

test('scale transforms linework, circles, arcs, text and inserts about a world point', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  const result = applyOps(opened, [
    { op: 'scale', layout: 'Model', ids: [ids.lineA, ids.circle, ids.arc, ids.text, ids.insert], center: [0, 0], factor: 2 }
  ])
  assert.equal(result.changes.scale, 5)
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  const entities = after.layouts.find(layout => layout.id === 'Model').entities
  const line = entities.find(entity => entity.id === ids.lineA)
  ok(line, 'the scaled line keeps its id')
  ok(nearPoints(line.pts, [[0, 0], [20, 0]]), `line scaled: ${JSON.stringify(line.pts)}`)
  const circle = entities.find(entity => entity.id === ids.circle)
  ok(nearPoint(circle.c, [40, 10]) && near(circle.r, 4), 'circle centre and radius scaled')
  const arc = entities.find(entity => entity.id === ids.arc)
  ok(nearPoint(arc.c, [60, 10]) && near(arc.r, 6), 'arc centre and radius scaled')
  assert.ok(near(arc.a0, 0) && near(arc.a1, Math.PI / 2), 'arc angles are unchanged by a uniform scale')
  const text = entities.find(entity => entity.id === ids.text)
  assert.ok(nearPoint(text.p, [100, 10]) && near(text.h, 1), 'text placement and height scaled')
  const insert = entities.find(entity => entity.id === ids.insert)
  assert.ok(nearPoint(insert.p, [120, 10]) && near(insert.scale[0], 2) && near(insert.scale[1], 2), 'insert placement and scale factors scaled')
  // Flattened block content follows the insert transform.
  const blockCircle = entities.find(entity => entity.k === 'circle' && entity.g === ids.insert)
  assert.ok(nearPoint(blockCircle.c, [120, 10]) && near(blockCircle.r, 1), 'block content scaled with its insert')
})

test('scale by 1 changes nothing and counts nothing', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  const before = buildSheetModel(opened)
  const result = applyOps(opened, [{ op: 'scale', layout: 'Model', ids: [ids.circle], center: [0, 0], factor: 1 }])
  assert.equal(result.changes.scale, undefined)
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  assert.deepEqual(topEntities(after).map(entity => entity.k), topEntities(before).map(entity => entity.k))
})

test('mirror keeps a mirrored copy by default and can erase the source', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  const keep = applyOps(opened, [
    // A horizontal axis at y = 5 puts the mirrored line at y = 10.
    { op: 'mirror', layout: 'Model', ids: [ids.lineA], axisA: [0, 5], axisB: [10, 5] },
    { op: 'mirror', layout: 'Model', ids: [ids.arc, ids.text], axisA: [0, 0], axisB: [1, 0] }
  ])
  assert.equal(keep.changes.mirror, 3)
  let after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  let entities = after.layouts.find(layout => layout.id === 'Model').entities
  ok(entities.some(entity => entity.id === ids.lineA), 'the source line is kept')
  ok(entities.some(entity => entity.k === 'line' && nearPoints(entity.pts, [[0, 10], [10, 10]])), 'the mirrored line is above the axis')
  const mirroredArc = entities.find(entity => entity.k === 'arc' && nearPoint(entity.c, [30, -5]))
  ok(mirroredArc, 'the mirrored arc centre is reflected')
  ok(near(mirroredArc.r, 3))
  // Reflection reverses the sweep: the mirrored quarter runs from 270° to 360°.
  assert.ok(near(mirroredArc.a0, (3 * Math.PI) / 2))
  assert.ok(near(mirroredArc.a1 % (Math.PI * 2), 0))
  const mirroredText = entities.find(entity => entity.k === 'text' && entity.t === 'NOTE' && nearPoint(entity.p, [50, -5]))
  ok(mirroredText, 'the mirrored text placement is reflected')
  assert.ok(near(mirroredText.rot, -0.3), 'text mirrors readably: placement and rotation reflect, glyphs do not')
  ok(entities.some(entity => entity.id === ids.text), 'the source text is kept')

  const erased = await openCad()
  const erasedIds = idsOf(buildSheetModel(erased))
  const erase = applyOps(erased, [
    { op: 'mirror', layout: 'Model', ids: [erasedIds.lineA], axisA: [0, 5], axisB: [10, 5], eraseSource: true }
  ])
  assert.equal(erase.changes.mirror, 1)
  after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(erased) }))
  entities = after.layouts.find(layout => layout.id === 'Model').entities
  assert.equal(entities.some(entity => entity.id === erasedIds.lineA), false, 'eraseSource removes the source')
  ok(entities.some(entity => entity.k === 'line' && nearPoints(entity.pts, [[0, 10], [10, 10]])), 'the mirrored line remains')
})

test('mirror flips a polyline bulge with the rest of the geometry', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  applyOps(opened, [{ op: 'mirror', layout: 'Model', ids: [ids.poly], axisA: [0, 0], axisB: [1, 0] }])
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  const polylines = topEntities(after).filter(entity => entity.k === 'polyline')
  assert.equal(polylines.length, 2)
  const source = polylines.find(entity => entity.id === ids.poly)
  const mirrored = polylines.find(entity => entity.id !== ids.poly)
  ok(source && mirrored, 'both the source and the mirrored polyline are present')
  // The bulge tessellated into points above y = 0; the mirrored copy has them below.
  const minY = Math.min(...mirrored.pts.map(point => point[1]))
  const maxY = Math.max(...source.pts.map(point => point[1]))
  assert.ok(minY < -1.5, `mirrored bulge is below the axis: ${minY}`)
  assert.ok(maxY > 2.5, `source bulge stays above the axis: ${maxY}`)
})

test('offset makes a parallel line, circle and arc on the picked side', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  const result = applyOps(opened, [
    { op: 'offset', layout: 'Model', id: ids.lineA, distance: 3, side: [0, 1] },
    { op: 'offset', layout: 'Model', id: ids.lineA, distance: 3, side: [0, -1] },
    { op: 'offset', layout: 'Model', id: ids.circle, distance: 1, side: [20, 10] },
    { op: 'offset', layout: 'Model', id: ids.circle, distance: 1, side: [20, 5] },
    { op: 'offset', layout: 'Model', id: ids.arc, distance: 0.5, side: [30, 10] }
  ])
  assert.equal(result.changes.offset, 5)
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  const entities = topEntities(after)
  ok(entities.some(entity => entity.k === 'line' && nearPoints(entity.pts, [[0, 3], [10, 3]])), 'line offset above')
  ok(entities.some(entity => entity.k === 'line' && nearPoints(entity.pts, [[0, -3], [10, -3]])), 'line offset below')
  const circles = entities.filter(entity => entity.k === 'circle' && nearPoint(entity.c, [20, 5]))
  assert.deepEqual(circles.map(entity => entity.r).sort((a, b) => a - b), [1, 2, 3], 'source circle, inward offset and outward offset')
  const arcs = entities.filter(entity => entity.k === 'arc' && nearPoint(entity.c, [30, 5]))
  assert.deepEqual(arcs.map(entity => entity.r).sort((a, b) => a - b), [3, 3.5], 'source arc and outward offset')
  // The offset copies are new entities; the sources keep their ids.
  ok(entities.some(entity => entity.id === ids.lineA))
  ok(entities.some(entity => entity.id === ids.circle))
  ok(entities.some(entity => entity.id === ids.arc))
})

test('trim cuts the picked end back to the boundary and extend reaches it', async () => {
  const endOpen = await openCad()
  const endIds = idsOf(buildSheetModel(endOpen))
  const endResult = applyOps(endOpen, [{ op: 'trim', layout: 'Model', id: endIds.lineA, boundaryId: endIds.lineV, pick: [10, 0] }])
  assert.equal(endResult.changes.trim, 1)
  let after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(endOpen) }))
  let line = after.layouts.find(layout => layout.id === 'Model').entities.find(entity => entity.id === endIds.lineA)
  ok(nearPoints(line.pts, [[0, 0], [5, 0]]), 'the end near the pick is trimmed to the crossing')

  const startOpen = await openCad()
  const startIds = idsOf(buildSheetModel(startOpen))
  applyOps(startOpen, [{ op: 'trim', layout: 'Model', id: startIds.lineA, boundaryId: startIds.lineV, pick: [0, 0] }])
  after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(startOpen) }))
  line = after.layouts.find(layout => layout.id === 'Model').entities.find(entity => entity.id === startIds.lineA)
  ok(nearPoints(line.pts, [[5, 0], [10, 0]]), 'the start near the pick is trimmed to the crossing')

  const noPickOpen = await openCad()
  const noPickIds = idsOf(buildSheetModel(noPickOpen))
  applyOps(noPickOpen, [{ op: 'trim', layout: 'Model', id: noPickIds.lineA, boundaryId: noPickIds.lineV }])
  after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(noPickOpen) }))
  line = after.layouts.find(layout => layout.id === 'Model').entities.find(entity => entity.id === noPickIds.lineA)
  // The crossing is the midpoint, so the nearest-end choice is the documented
  // deterministic tie-break: the start end.
  ok(nearPoints(line.pts, [[5, 0], [10, 0]]), `no-pick tie-break chooses the start: ${JSON.stringify(line.pts)}`)

  const extendOpen = await openCad()
  const extendIds = idsOf(buildSheetModel(extendOpen))
  const extendResult = applyOps(extendOpen, [{ op: 'extend', layout: 'Model', id: extendIds.lineS, boundaryId: extendIds.lineE }])
  assert.equal(extendResult.changes.extend, 1)
  after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(extendOpen) }))
  line = after.layouts.find(layout => layout.id === 'Model').entities.find(entity => entity.id === extendIds.lineS)
  ok(nearPoints(line.pts, [[0, 2], [10, 2]]), 'the nearer end extends to the boundary')
})

test('setLine and setPolyline replace grip-edited geometry', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  const result = applyOps(opened, [
    { op: 'setLine', layout: 'Model', id: ids.lineA, a: [1, 1], b: [9, 9] },
    { op: 'setPolyline', layout: 'Model', id: ids.poly, pts: [[40, 0], [46, 0], [46, 4]], closed: true }
  ])
  assert.equal(result.changes.setLine, 1)
  assert.equal(result.changes.setPolyline, 1)
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  const entities = after.layouts.find(layout => layout.id === 'Model').entities
  const line = entities.find(entity => entity.id === ids.lineA)
  ok(nearPoints(line.pts, [[1, 1], [9, 9]]), 'the line endpoints are replaced')
  const polyline = entities.find(entity => entity.id === ids.poly)
  // A closed polyline reads back with the seam point repeated at the end.
  ok(nearPoints(polyline.pts.slice(0, 3), [[40, 0], [46, 0], [46, 4]]) && nearPoint(polyline.pts[3], [40, 0]), 'the polyline vertices are replaced')
  assert.equal(polyline.closed, true)
  assert.equal(polyline.layer, 'GEOM')

  // Setting the same geometry counts nothing, because nothing changed. The
  // polyline is first rewritten to straight vertices, then set to those very
  // vertices again; the second apply must not report a change.
  const noopOpen = await openCad()
  const noopIds = idsOf(buildSheetModel(noopOpen))
  const straight = [[40, 0], [46, 0], [46, 4]]
  applyOps(noopOpen, [{ op: 'setPolyline', layout: 'Model', id: noopIds.poly, pts: straight, closed: true }])
  const noop = applyOps(noopOpen, [
    { op: 'setLine', layout: 'Model', id: noopIds.lineA, a: [0, 0], b: [10, 0] },
    { op: 'setPolyline', layout: 'Model', id: noopIds.poly, pts: straight, closed: true }
  ])
  assert.equal(noop.changes.setLine, undefined)
  assert.equal(noop.changes.setPolyline, undefined)
})

test('addLayer, setLayerColor and renameLayer update the table and entity references', async () => {
  const opened = await openCad()
  const ids = idsOf(buildSheetModel(opened))
  const baseModel = buildSheetModel(opened)
  const result = applyOps(opened, [
    { op: 'addLayer', name: 'MARKUP', color: 5 },
    { op: 'setLayerColor', name: 'GEOM', color: 6 },
    { op: 'renameLayer', from: 'AUX', to: 'AUX2' }
  ])
  assert.deepEqual(result.changes, { addLayer: 1, setLayerColor: 1, renameLayer: 1 })
  assert.equal(result.touchedIds.length, 0, 'layer edits touch no entity handle')
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  const byName = new Map(after.layers.map(layer => [layer.name, layer]))
  assert.equal(byName.has('AUX'), false, 'the old layer name is gone from the table')
  const renamed = byName.get('AUX2')
  ok(renamed, 'the renamed layer is in the table')
  assert.equal(renamed.color, 4, 'a rename keeps the layer colour')
  assert.equal(byName.get('GEOM').color, 6, 'setLayerColor changes the layer colour')
  const markup = byName.get('MARKUP')
  ok(markup, 'addLayer creates the layer')
  assert.equal(markup.color, 5)
  const entities = after.layouts.find(layout => layout.id === 'Model').entities
  ok(entities.some(entity => entity.id === ids.lineA && entity.layer === 'GEOM' && entity.color === 6), 'by-layer entities follow the layer colour')
  ok(entities.some(entity => entity.id === ids.lineV && entity.layer === 'AUX2'), 'a top-level entity reference moved with the rename')
  // Geometry flattened out of the MARK block is carried on AUX, so the writer
  // must have moved the block definition's entity references too.
  ok(entities.some(entity => entity.g === ids.insert && entity.layer === 'AUX2'), 'block-definition entity references moved with the rename')

  // The write verification observes the layer table, not just primitives.
  const verification = await verifyWritten(opened, dxfBytes(opened), { changes: result.changes, baseModel })
  assert.equal(verification.ok, true)
  assert.deepEqual(verification.problems, [])
  assert.equal(verification.applied.addLayer, 2, 'MARKUP and RENAMED are both new names')
  assert.equal(verification.applied.renameLayer, 1)
  assert.equal(verification.applied.setLayerColor, 1)
})

test('a write and re-read round trip carries copy, scale, mirror, addCircle and addArc', async () => {
  const opened = await openCad()
  const baseModel = buildSheetModel(opened)
  const ids = idsOf(baseModel)
  const ops = [
    { op: 'addCircle', layout: 'Model', center: [70, 0], radius: 1.5 },
    { op: 'addArc', layout: 'Model', center: [75, 0], radius: 2, startAngleDeg: 30, endAngleDeg: 120 },
    { op: 'copy', layout: 'Model', ids: [ids.lineA], dx: 0, dy: 20 },
    { op: 'scale', layout: 'Model', ids: [ids.circle, ids.text], center: [20, 5], factor: 1.5 },
    { op: 'mirror', layout: 'Model', ids: [ids.poly], axisA: [0, 0], axisB: [1, 0] }
  ]
  assert.equal(validateOps(opened, ops).ok, true)
  const result = applyOps(opened, ops)
  assert.deepEqual(result.changes, { addCircle: 1, addArc: 1, copy: 1, scale: 2, mirror: 1 })

  const bytes = dxfBytes(opened)
  const verification = await verifyWritten(opened, bytes, { changes: result.changes, baseModel })
  assert.equal(verification.ok, true, JSON.stringify(verification.problems))
  assert.deepEqual(verification.problems, [])
  assert.equal(verification.applied.addCircle, 1)
  assert.equal(verification.applied.addArc, 1)
  assert.ok(verification.applied.copy >= 1)
  assert.ok(verification.applied.mirror >= 1)
  assert.ok(verification.applied.scale >= 2)

  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes }))
  const entities = after.layouts.find(layout => layout.id === 'Model').entities
  ok(entities.some(entity => entity.k === 'circle' && nearPoint(entity.c, [70, 0]) && near(entity.r, 1.5)), 'the added circle survives the write')
  const arc = entities.find(entity => entity.k === 'arc' && nearPoint(entity.c, [75, 0]))
  ok(arc && near(arc.r, 2) && near(arc.a0, Math.PI / 6) && near(arc.a1, (2 * Math.PI) / 3), 'the added arc survives the write')
  ok(entities.some(entity => entity.k === 'line' && nearPoints(entity.pts, [[0, 20], [10, 20]])), 'the copy survives the write')
  const scaledCircle = entities.find(entity => entity.id === ids.circle)
  ok(near(scaledCircle.c[0], 20) && near(scaledCircle.c[1], 5) && near(scaledCircle.r, 3), 'the scaled circle survives the write')
  const scaledText = entities.find(entity => entity.id === ids.text)
  assert.ok(nearPoint(scaledText.p, [65, 5]) && near(scaledText.h, 0.75), 'the scaled text survives the write')
  const polylines = entities.filter(entity => entity.k === 'polyline')
  assert.equal(polylines.length, 2, 'the mirrored polyline is an added entity beside its source')
  ok(polylines.some(entity => entity.id === ids.poly), 'the mirror source survives the write')
  ok(polylines.some(entity => entity.id !== ids.poly && Math.min(...entity.pts.map(point => point[1])) < -1.5), 'the mirrored polyline survives the write')
})

test('a layer created and recoloured in one draft still verifies', async () => {
  const opened = await openCad()
  const baseModel = buildSheetModel(opened)
  const result = applyOps(opened, [
    { op: 'addLayer', name: 'MARKUP' },
    { op: 'setLayerColor', name: 'MARKUP', color: 5 }
  ])
  assert.deepEqual(result.changes, { addLayer: 1, setLayerColor: 1 })
  const verification = await verifyWritten(opened, dxfBytes(opened), { changes: result.changes, baseModel })
  assert.equal(verification.ok, true, JSON.stringify(verification.problems))
  // The new layer's final colour is carried by the written record, so the
  // creation of the layer is what evidences it; the observed table difference
  // is one added name and no recoloured name.
  assert.equal(verification.applied.addLayer, 1)
  assert.equal(verification.applied.setLayerColor, 0)
  const after = buildSheetModel(await openSheet({ path: CAD_FIXTURE, bytes: dxfBytes(opened) }))
  assert.equal(after.layers.find(layer => layer.name === 'MARKUP').color, 5)
})

test('the same draft applied twice produces the same drawing', async () => {
  const ids = idsOf(buildSheetModel(await openCad()))
  const ops = [
    { op: 'addCircle', layout: 'Model', center: [70, 0], radius: 1.5 },
    { op: 'copy', layout: 'Model', ids: [ids.lineA], dx: 0, dy: 20 },
    { op: 'scale', layout: 'Model', ids: [ids.circle], center: [20, 5], factor: 2 },
    { op: 'mirror', layout: 'Model', ids: [ids.poly], axisA: [0, 0], axisB: [1, 0] }
  ]
  const describe = model => model.layouts.flatMap(layout => layout.entities.map(entity => ({ k: entity.k, layer: entity.layer, c: entity.c, r: entity.r, p: entity.p, h: entity.h, pts: entity.pts, closed: entity.closed, a0: entity.a0, a1: entity.a1 })))
  const first = await applyAndReread(ops)
  const second = await applyAndReread(ops)
  assert.deepEqual(first.result.changes, second.result.changes)
  assert.deepEqual(describe(first.after), describe(second.after))
})
